-- ============================================================================
-- The Accessories Hub — Supabase schema, RLS and seed data
--
-- How to use:
--   1. Create (or restore) a project at https://supabase.com/dashboard
--   2. Open SQL Editor → New query → paste this whole file → Run
--   3. Settings → API → copy "Project URL" and the "anon public" key
--   4. Paste them into js/supabase-client.js (top of file)
--   5. Sign in once, then promote your account to admin (last statement below)
--
-- Safe to re-run: it drops and recreates policies/functions, and the catalog
-- seed only touches the rows it inserts.
-- ============================================================================

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
-- ---------------------------------------------------------------------------
-- Categories
-- ---------------------------------------------------------------------------
create table if not exists public.categories (
  id               uuid primary key default gen_random_uuid(),
  name             text not null,
  slug             text not null unique,
  description      text default '',
  image_url        text default '',
  seo_title        text default '',
  seo_description  text default '',
  is_active        boolean not null default true,
  sort_order       integer not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create table if not exists public.products (
  id             bigint primary key generated by default as identity,
  name           text not null,
  price          numeric(12,2) not null default 0,
  original_price numeric(12,2),
  collection     text default '',
  category       text default '',
  material       text default '',
  badge          text,
  image          text default '',
  images         jsonb not null default '[]'::jsonb,
  description    text default '',
  features       jsonb not null default '[]'::jsonb,
  stock          integer not null default 0,
  reorder_level  integer not null default 5,
  in_stock       boolean not null default true,
  sku            text,
  created_at     timestamptz not null default now()
);

create table if not exists public.customers (
  id           bigint primary key generated by default as identity,
  name         text not null,
  email        text default '',
  phone        text not null,
  address      text default '',
  notes        text default '',
  total_orders integer not null default 0,
  total_spent  numeric(12,2) not null default 0,
  join_date    timestamptz not null default now()
);
create unique index if not exists customers_phone_key on public.customers (phone);

create table if not exists public.orders (
  id               bigint primary key generated by default as identity,
  customer_id      bigint references public.customers(id) on delete set null,
  customer_name    text not null,
  subtotal         numeric(12,2) not null default 0,
  shipping         numeric(12,2) not null default 0,
  total            numeric(12,2) not null default 0,
  status           text not null default 'pending',
  payment          text not null default 'cod',
  shipping_address text default '',
  tracking_id      text,
  date             text,                      -- YYYY-MM-DD, kept as text for the admin UI
  created_at       timestamptz not null default now()
);

create table if not exists public.order_items (
  id         bigint primary key generated by default as identity,
  order_id   bigint references public.orders(id) on delete cascade,
  product_id bigint references public.products(id) on delete set null,
  name       text not null,
  price      numeric(12,2) not null default 0,
  qty        integer not null default 1,
  image      text default ''
);

create table if not exists public.invoices (
  id            text primary key,
  order_id      bigint references public.orders(id) on delete cascade,
  customer_name text default '',
  amount        numeric(12,2) not null default 0,
  status        text not null default 'unpaid',
  date          text,
  created_at    timestamptz not null default now()
);

create table if not exists public.stock_history (
  id            bigint primary key generated by default as identity,
  product       text default '',
  product_name  text default '',
  type          text default 'adjustment',
  change_amount integer not null default 0,
  new_stock     integer not null default 0,
  date          text,
  created_at    timestamptz not null default now()
);

create table if not exists public.settings (
  id                integer primary key default 1,
  business_name     text default 'The Accessories Hub',
  business_address  text default 'Birgunj, Nepal',
  business_phone    text default '+977 9805659501',
  business_email    text default 'theaccessorieshub2530@gmail.com',
  whatsapp_number   text default '9805659501',
  whatsapp_templates jsonb default '{}'::jsonb,
  shipping_providers jsonb default '[]'::jsonb,
  updated_at        timestamptz not null default now(),
  constraint settings_single_row check (id = 1)
);

create table if not exists public.profiles (
  id         uuid primary key references auth.users(id) on delete cascade,
  email      text,
  role       text not null default 'user',
  created_at timestamptz not null default now()
);

