insert into public.products
  (id, name, price, original_price, collection, category, material, badge,
   image, images, description, features, stock, reorder_level, in_stock, sku)
select id, name, price, original_price, collection, category, material, badge,
       image, images, description, features, stock, reorder_level, in_stock, sku
