rom day to night.","features":["Tarnish-Free","Waterproof","Hypoallergenic"],"stock":25,"reorder_level":5,"in_stock":true,"sku":"TAH-011"},{"id":12,"name":"Royal Temple Choker","price":3800,"original_price":4500,"collection":"temple","category":"necklaces","material":"Gold Plated","badge":"Best Seller","image":"images/temple-necklace.png","images":["images/temple-necklace.png"],"description":"An opulent temple-style gold choker necklace featuring detailed stone-work and floral motifs. This regal piece is designed to make a grand statement at weddings and celebrations.","features":["Tarnish-Free","Handcrafted","Hypoallergenic"],"stock":25,"reorder_level":5,"in_stock":true,"sku":"TAH-012"}]$catalog$::jsonb) as t(
  id bigint, name text, price numeric, original_price numeric, collection text,
