-- ============================================================================
-- The Accessories Hub — ERP & Business Management Schema Additions
-- ============================================================================

-- 1. Product & Order Enhancements for ERP Costing & Discounts
alter table public.products add column if not exists cost_price numeric(12,2) default 0;
alter table public.products add column if not exists weight_grams numeric(8,2) default 0;
alter table public.products add column if not exists metal_purity text default '';
alter table public.products add column if not exists is_archived boolean default false;

alter table public.orders add column if not exists discount_amount numeric(12,2) default 0;
alter table public.orders add column if not exists coupon_code text default '';
alter table public.orders add column if not exists notes text default '';
alter table public.orders add column if not exists payment_status text default 'pending';

-- 2. Suppliers & Purchasing
create table if not exists public.suppliers (
  id               bigint primary key generated by default as identity,
  name             text not null,
  contact_name     text default '',
  email            text default '',
  phone            text default '',
  address          text default '',
  tax_id           text default '',
  payment_terms    text default 'Net 30',
  lead_time_days   integer default 7,
  notes            text default '',
  created_at       timestamptz not null default now()
);

create table if not exists public.purchase_orders (
  id               bigint primary key generated by default as identity,
  po_number        text not null unique,
  supplier_id      bigint references public.suppliers(id) on delete set null,
  supplier_name    text default '',
  status           text not null default 'draft', -- 'draft', 'approved', 'ordered', 'partially_received', 'received', 'cancelled'
  order_date       text default to_char(now(), 'YYYY-MM-DD'),
  expected_date    text,
  subtotal         numeric(12,2) not null default 0,
  tax              numeric(12,2) not null default 0,
  shipping         numeric(12,2) not null default 0,
  total            numeric(12,2) not null default 0,
  notes            text default '',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create table if not exists public.purchase_order_items (
  id               bigint primary key generated by default as identity,
  po_id            bigint references public.purchase_orders(id) on delete cascade,
  product_id       bigint references public.products(id) on delete set null,
  product_name     text not null,
  sku              text default '',
  unit_cost        numeric(12,2) not null default 0,
  ordered_qty      integer not null default 1,
  received_qty     integer not null default 0,
  total_cost       numeric(12,2) not null default 0
);

-- 3. Expenses & Operational Finance
create table if not exists public.expenses (
  id               bigint primary key generated by default as identity,
  reference_no     text not null,
  date             text not null default to_char(now(), 'YYYY-MM-DD'),
  category         text not null, -- 'Inventory', 'Packaging', 'Shipping', 'Marketing', 'Software', 'Salaries', 'Rent', 'Utilities', 'Office', 'Other'
  description      text not null,
  amount           numeric(12,2) not null default 0,
  payee            text default '',
  payment_method   text default 'Cash',
  payment_status   text default 'paid', -- 'paid', 'unpaid', 'pending'
  receipt_url      text default '',
  approved_by      text default '',
  created_at       timestamptz not null default now()
);

-- 4. Shipping & Delivery
create table if not exists public.shipments (
  id               bigint primary key generated by default as identity,
  order_id         bigint references public.orders(id) on delete cascade,
  courier_name     text default 'Nepal Post',
  tracking_number  text default '',
  shipping_cost    numeric(12,2) default 0,
  status           text default 'pending', -- 'pending', 'picked_up', 'in_transit', 'out_for_delivery', 'delivered', 'failed', 'returned'
  dispatched_at    timestamptz,
  delivered_at     timestamptz,
  notes            text default '',
  created_at       timestamptz not null default now()
);

-- 5. Returns & Refunds
create table if not exists public.returns_refunds (
  id               bigint primary key generated by default as identity,
  return_number    text not null unique,
  order_id         bigint references public.orders(id) on delete cascade,
  customer_name    text default '',
  customer_phone   text default '',
  type             text default 'return', -- 'return', 'exchange', 'refund'
  reason           text default '',
  condition        text default 'good', -- 'unopened', 'good', 'damaged', 'defective'
  status           text default 'requested', -- 'requested', 'approved', 'received', 'restocked', 'refunded', 'rejected'
  refund_amount    numeric(12,2) default 0,
  refund_method    text default 'bank_transfer',
  restock_approved boolean default false,
  notes            text default '',
  created_at       timestamptz not null default now(),
  resolved_at      timestamptz
);

-- 6. Marketing, Discounts & Coupons
create table if not exists public.coupons (
  id               bigint primary key generated by default as identity,
  code             text not null unique,
  description      text default '',
  discount_type    text default 'percentage', -- 'percentage', 'fixed'
  discount_value   numeric(12,2) not null default 0,
  min_order_amount numeric(12,2) default 0,
  max_discount     numeric(12,2) default 0,
  usage_limit      integer default 100,
  times_used       integer default 0,
  start_date       text,
  expires_at       text,
  is_active        boolean default true,
  created_at       timestamptz not null default now()
);

-- 7. Audit Trail
create table if not exists public.audit_logs (
  id               bigint primary key generated by default as identity,
  user_id          uuid references auth.users(id) on delete set null,
  user_email       text default '',
  action           text not null,
  entity_type      text not null,
  entity_id        text default '',
  details          text default '',
  ip_address       text default '',
  created_at       timestamptz not null default now()
);

-- 8. Notifications & Alerts
create table if not exists public.notifications (
  id               bigint primary key generated by default as identity,
  title            text not null,
  message          text not null,
  type             text default 'info', -- 'order', 'stock', 'payment', 'return', 'system', 'info'
  link             text default '',
  is_read          boolean default false,
  created_at       timestamptz not null default now()
);

-- 9. Customer Reviews & Feedback
create table if not exists public.reviews (
  id               bigint primary key generated by default as identity,
  product_id       bigint references public.products(id) on delete cascade,
  product_name     text default '',
  customer_name    text not null,
  rating           integer not null default 5,
  comment          text default '',
  is_approved      boolean default true,
  created_at       timestamptz not null default now()
);

-- 10. Enable Row-Level Security on All ERP Tables
alter table public.suppliers            enable row level security;
alter table public.purchase_orders       enable row level security;
alter table public.purchase_order_items enable row level security;
alter table public.expenses             enable row level security;
alter table public.shipments            enable row level security;
alter table public.returns_refunds      enable row level security;
alter table public.coupons              enable row level security;
alter table public.audit_logs           enable row level security;
alter table public.notifications        enable row level security;
alter table public.reviews              enable row level security;

-- Admin policies
drop policy if exists suppliers_admin on public.suppliers;
create policy suppliers_admin on public.suppliers
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists po_admin on public.purchase_orders;
create policy po_admin on public.purchase_orders
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists po_items_admin on public.purchase_order_items;
create policy po_items_admin on public.purchase_order_items
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists expenses_admin on public.expenses;
create policy expenses_admin on public.expenses
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists shipments_admin on public.shipments;
create policy shipments_admin on public.shipments
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists returns_admin on public.returns_refunds;
create policy returns_admin on public.returns_refunds
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists audit_logs_admin on public.audit_logs;
create policy audit_logs_admin on public.audit_logs
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists notifications_admin on public.notifications;
create policy notifications_admin on public.notifications
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Coupons: Public read for active coupons; admin full access
drop policy if exists coupons_public_read on public.coupons;
create policy coupons_public_read on public.coupons
  for select to anon, authenticated using (is_active = true or public.is_admin());

drop policy if exists coupons_admin on public.coupons;
create policy coupons_admin on public.coupons
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Reviews: Public read for approved reviews; admin full access; authenticated/anon insert
drop policy if exists reviews_public_read on public.reviews;
create policy reviews_public_read on public.reviews
  for select to anon, authenticated using (is_approved = true or public.is_admin());

drop policy if exists reviews_insert on public.reviews;
create policy reviews_insert on public.reviews
  for insert to anon, authenticated with check (true);

drop policy if exists reviews_admin on public.reviews;
create policy reviews_admin on public.reviews
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Helper function: Audit Log
create or replace function public.log_audit_event(
  p_action text,
  p_entity_type text,
  p_entity_id text,
  p_details text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.audit_logs (user_id, user_email, action, entity_type, entity_id, details)
  values (
    auth.uid(),
    coalesce((select email from auth.users where id = auth.uid()), 'system'),
    p_action,
    p_entity_type,
    p_entity_id,
    p_details
  );
end;
$$;


-- ============================================================================
-- The Accessories Hub — Performance Optimization & Complete Inventory
-- ============================================================================
alter table public.products add column if not exists color text default '';
alter table public.products add column if not exists audience text default 'unisex';
alter table public.products add column if not exists variants jsonb default '[]'::jsonb;
alter table public.products add column if not exists location text default 'Main Warehouse';
alter table public.products add column if not exists supplier_id bigint references public.suppliers(id) on delete set null;
alter table public.products add column if not exists reserved_stock integer not null default 0;

alter table public.stock_history add column if not exists product_id bigint references public.products(id) on delete set null;
alter table public.stock_history add column if not exists reason text default '';
alter table public.stock_history add column if not exists user_email text default '';

create index if not exists idx_products_sku on public.products (sku);
create index if not exists idx_products_in_stock on public.products (in_stock);
create index if not exists idx_products_is_archived on public.products (is_archived);
create index if not exists idx_products_category on public.products (category);
create index if not exists idx_products_price on public.products (price);
create index if not exists idx_orders_created_at on public.orders (created_at desc);
create index if not exists idx_orders_status on public.orders (status);
create index if not exists idx_stock_history_product_id on public.stock_history (product_id);
create index if not exists idx_stock_history_created_at on public.stock_history (created_at desc);
create index if not exists idx_expenses_date on public.expenses (date desc);
create index if not exists idx_notifications_is_read on public.notifications (is_read);
